#!/bin/bash\n\necho \"Building Pulse Hospital Frontend for Vercel Deployment...\"\n\n# Install dependencies\necho \"Installing dependencies...\"\nnpm install\n\n# Build the application for production\necho \"Building application...\"\nnpm run build:prod\n\necho \"Build completed successfully!\"\necho \"Files are ready for deployment in the 'dist/hms' folder.\"\necho \"\"\necho \"Deployment Instructions:\"\necho \"1. Install Vercel CLI: npm i -g vercel\"\necho \"2. Login to Vercel: vercel login\"\necho \"3. Deploy: vercel --prod\"\necho \"4. Update environment.prod.ts with your Monster ASP API URL\"\necho \"5. Update CORS settings in your backend to include your Vercel domain\"\necho \"\"\necho \"For microfrontend integration:\"\necho \"- Use the exported components from microfrontend.module.ts\"\necho \"- Load the application using the bootstrap function from microfrontend.ts\"\necho \"- The app can be mounted/unmounted dynamically for microfrontend architecture\"